void CompressorProcessor::process(juce::AudioBuffer<float>& buffer) {
    if (!isEnabled) return;
    juce::dsp::AudioBlock<float> block(buffer);
    juce::dsp::ProcessContextReplacing<float> context(block);
    compressor.process(context);
}

