class NoiseGateProcessor : public EffectProcessor {
private:
    float threshold = 0.3f;
    float reduction = 2.0f;
    float preservation = 0.1f;
    float frequencyFocus = 1.5f;
    float gateState = 1.0f;
    float attackCoeff = 0.1f;
    float releaseCoeff = 0.999f;
};

void NoiseGateProcessor::process(juce::AudioBuffer<float>& buffer) {
    if (!isEnabled) return;
    for (int channel = 0; channel < buffer.getNumChannels(); ++channel) {
        auto* channelData = buffer.getWritePointer(channel);
        for (int sample = 0; sample < buffer.getNumSamples(); ++sample) {
            float absInput = std::abs(channelData[sample]);
            if (absInput < threshold) {
                float reductionFactor = 1.0f - (reduction - 1.0f) / 2.0f;
                channelData[sample] *= std::max(reductionFactor, preservation);
            }
        }
    }
}

void WavePreviewPage::drawSpectralWaveform(juce::Graphics& g, juce::Rectangle<int> area,
                                            double startTime, double endTime) {
